-- Gio database setup: every migration in supabase/migrations, in order.
-- Run this once on a new Supabase project (SQL Editor > New query > paste > Run).
-- Generated by scripts/build-setup-sql.mjs; edit the migrations, not this file.

-- ===== 20260928000001_foundation.sql =====

-- Gio foundation schema.
--
-- Single-household app: one Supabase Auth account shared by Courtney and Amar.
-- Every row carries user_id and every table has row-level security scoped to
-- auth.uid(). Storage buckets are private; objects live under "<user_id>/...".
--
-- Embedding dimension: vector(1024) matches Voyage `voyage-4` at its default
-- output dimension. If you change EMBEDDING_DIMENSION / EMBEDDING_MODEL, write a
-- new migration that alters these columns and re-index (Settings > Files).

create extension if not exists vector with schema extensions;

-- ---------------------------------------------------------------------------
-- Helpers
-- ---------------------------------------------------------------------------

create or replace function public.set_updated_at()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

-- ---------------------------------------------------------------------------
-- users: profile row mirroring auth.users (one row for the household)
-- ---------------------------------------------------------------------------

create table public.users (
  id uuid primary key references auth.users (id) on delete cascade,
  email text,
  display_name text not null default 'Courtney & Amar',
  last_speaker text not null default 'Both'
    check (last_speaker in ('Courtney', 'Amar', 'Both')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- ---------------------------------------------------------------------------
-- projects and rooms
-- ---------------------------------------------------------------------------

create table public.projects (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null default auth.uid() references public.users (id) on delete cascade,
  name text not null check (length(trim(name)) > 0),
  location text,
  -- Free-form brief: architecture, place, climate, how the home is used,
  -- constraints. Shown to Gio as PROJECT CONTEXT on every turn.
  brief text,
  is_default boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- Exactly one "General Design Brain" per user.
create unique index projects_one_default_per_user
  on public.projects (user_id) where is_default;
create index projects_user_idx on public.projects (user_id);

create table public.rooms (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null default auth.uid() references public.users (id) on delete cascade,
  project_id uuid not null references public.projects (id) on delete cascade,
  name text not null check (length(trim(name)) > 0),
  notes text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index rooms_project_idx on public.rooms (project_id);
-- No two rooms with the same name in one project.
create unique index rooms_unique_name on public.rooms (project_id, lower(trim(name)));

-- ---------------------------------------------------------------------------
-- chats and messages
-- ---------------------------------------------------------------------------

create table public.chats (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null default auth.uid() references public.users (id) on delete cascade,
  project_id uuid not null references public.projects (id) on delete cascade,
  room_id uuid references public.rooms (id) on delete set null,
  title text,
  -- 'app' for chats created here, 'chatgpt' for imported conversations.
  source text not null default 'app',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index chats_project_idx on public.chats (project_id, updated_at desc);

create table public.messages (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null default auth.uid() references public.users (id) on delete cascade,
  chat_id uuid not null references public.chats (id) on delete cascade,
  role text not null check (role in ('user', 'assistant')),
  speaker text not null check (speaker in ('Courtney', 'Amar', 'Both', 'Gio')),
  -- Plain text of the message (assistant: concatenated text blocks).
  content text not null default '',
  -- Attached images / files: [{ image_asset_id, storage_path, mime_type, name }]
  attachments jsonb not null default '[]'::jsonb,
  -- Model, usage, web sources, retrieved reference ids, stop reason, etc.
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  constraint messages_speaker_matches_role check (
    (role = 'assistant' and speaker = 'Gio')
    or (role = 'user' and speaker in ('Courtney', 'Amar', 'Both'))
  )
);
create index messages_chat_idx on public.messages (chat_id, created_at);

-- ---------------------------------------------------------------------------
-- files, image assets, chunks (reference library)
-- ---------------------------------------------------------------------------

create table public.files (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null default auth.uid() references public.users (id) on delete cascade,
  project_id uuid not null references public.projects (id) on delete cascade,
  room_id uuid references public.rooms (id) on delete set null,
  name text not null,
  mime_type text not null,
  size_bytes bigint not null default 0,
  storage_path text not null,
  status text not null default 'pending'
    check (status in ('pending', 'processing', 'indexed', 'failed')),
  error text,
  page_count int,
  chunk_count int not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  indexed_at timestamptz
);
create index files_project_idx on public.files (project_id, created_at desc);

create table public.image_assets (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null default auth.uid() references public.users (id) on delete cascade,
  project_id uuid not null references public.projects (id) on delete cascade,
  room_id uuid references public.rooms (id) on delete set null,
  -- Set when the image is an uploaded file or a rendered page of one.
  file_id uuid references public.files (id) on delete cascade,
  page int,
  -- Set when the image was attached to a chat message.
  message_id uuid references public.messages (id) on delete set null,
  storage_path text not null,
  mime_type text not null,
  width int,
  height int,
  description text,
  created_at timestamptz not null default now()
);
create index image_assets_project_idx on public.image_assets (project_id);
create index image_assets_file_idx on public.image_assets (file_id);

create table public.chunks (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null default auth.uid() references public.users (id) on delete cascade,
  file_id uuid references public.files (id) on delete cascade,
  image_asset_id uuid references public.image_assets (id) on delete cascade,
  project_id uuid not null references public.projects (id) on delete cascade,
  room_id uuid references public.rooms (id) on delete set null,
  source_type text not null check (source_type in ('text', 'visual_description')),
  content text not null,
  page int,
  chunk_index int not null default 0,
  token_count int,
  metadata jsonb not null default '{}'::jsonb,
  embedding extensions.vector(1024),
  created_at timestamptz not null default now()
);
create index chunks_project_idx on public.chunks (project_id);
create index chunks_file_idx on public.chunks (file_id);
create index chunks_embedding_idx on public.chunks
  using hnsw (embedding extensions.vector_cosine_ops);

-- ---------------------------------------------------------------------------
-- memories, decisions, products
-- ---------------------------------------------------------------------------

create table public.memories (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null default auth.uid() references public.users (id) on delete cascade,
  -- null project_id = household-wide (applies across every project).
  project_id uuid references public.projects (id) on delete cascade,
  room_id uuid references public.rooms (id) on delete set null,
  type text not null check (type in (
    'design_preference', 'courtney_preference', 'amar_preference',
    'shared_preference', 'rejected_idea', 'approved_decision',
    'project_constraint', 'budget_philosophy', 'material', 'vendor',
    'dimension', 'paint_color', 'furniture_under_consideration'
  )),
  content text not null check (length(trim(content)) > 0),
  -- Who the memory belongs to, from the message speaker field.
  attributed_to text check (attributed_to in ('Courtney', 'Amar', 'Both')),
  -- Proposed items wait in the right panel; only 'approved' reach Gio.
  review_state text not null default 'approved'
    check (review_state in ('proposed', 'approved', 'dismissed')),
  source_message_id uuid references public.messages (id) on delete set null,
  embedding extensions.vector(1024),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index memories_project_idx on public.memories (project_id, review_state);

create table public.products (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null default auth.uid() references public.users (id) on delete cascade,
  project_id uuid not null references public.projects (id) on delete cascade,
  room_id uuid references public.rooms (id) on delete set null,
  name text not null,
  designer text,
  vendor text,
  url text,
  dimensions text,
  material_color text,
  provenance text check (provenance in ('vintage', 'new', 'antique', 'custom', 'unknown')),
  price_amount numeric(12, 2),
  price_currency text default 'USD',
  price_basis text check (price_basis in ('sourced', 'estimated')),
  price_source_url text,
  placement text,
  rationale text,
  verdict text check (verdict in ('invest', 'save', 'skip')),
  status text not null default 'considering'
    check (status in ('considering', 'approved', 'rejected', 'purchased')),
  image_asset_id uuid references public.image_assets (id) on delete set null,
  source_message_id uuid references public.messages (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index products_project_idx on public.products (project_id);

create table public.decisions (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null default auth.uid() references public.users (id) on delete cascade,
  project_id uuid not null references public.projects (id) on delete cascade,
  room_id uuid references public.rooms (id) on delete set null,
  title text not null check (length(trim(title)) > 0),
  detail text,
  status text not null default 'pending'
    check (status in ('approved', 'keep_looking', 'rejected', 'pending')),
  review_state text not null default 'approved'
    check (review_state in ('proposed', 'approved', 'dismissed')),
  product_id uuid references public.products (id) on delete set null,
  source_message_id uuid references public.messages (id) on delete set null,
  decided_by text check (decided_by in ('Courtney', 'Amar', 'Both')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index decisions_project_idx on public.decisions (project_id, review_state);

-- ---------------------------------------------------------------------------
-- settings: key/value per user (system prompt lives under 'system_prompt')
-- ---------------------------------------------------------------------------

create table public.settings (
  user_id uuid not null default auth.uid() references public.users (id) on delete cascade,
  key text not null,
  value jsonb not null,
  updated_at timestamptz not null default now(),
  primary key (user_id, key)
);

-- ---------------------------------------------------------------------------
-- updated_at triggers
-- ---------------------------------------------------------------------------

create trigger users_updated_at before update on public.users
  for each row execute function public.set_updated_at();
create trigger projects_updated_at before update on public.projects
  for each row execute function public.set_updated_at();
create trigger rooms_updated_at before update on public.rooms
  for each row execute function public.set_updated_at();
create trigger chats_updated_at before update on public.chats
  for each row execute function public.set_updated_at();
create trigger files_updated_at before update on public.files
  for each row execute function public.set_updated_at();
create trigger memories_updated_at before update on public.memories
  for each row execute function public.set_updated_at();
create trigger products_updated_at before update on public.products
  for each row execute function public.set_updated_at();
create trigger decisions_updated_at before update on public.decisions
  for each row execute function public.set_updated_at();
create trigger settings_updated_at before update on public.settings
  for each row execute function public.set_updated_at();

-- Posting a message bumps the chat so the sidebar sorts by recent activity.
create or replace function public.touch_chat()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  update public.chats set updated_at = now() where id = new.chat_id;
  return new;
end;
$$;

create trigger messages_touch_chat after insert on public.messages
  for each row execute function public.touch_chat();

-- ---------------------------------------------------------------------------
-- New auth user -> profile row + "General Design Brain" project.
-- (The system prompt is written by `npm run bootstrap` and, as a fallback, by
-- the app on first read, so the verbatim prompt has one source of truth in
-- src/lib/gio/default-system-prompt.ts.)
-- ---------------------------------------------------------------------------

create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  insert into public.users (id, email) values (new.id, new.email)
  on conflict (id) do nothing;

  insert into public.projects (user_id, name, brief, is_default)
  values (
    new.id,
    'General Design Brain',
    'Household-wide design thinking that applies across every home and project: '
      || 'taste, principles, references and lessons learned.',
    true
  )
  on conflict do nothing;

  return new;
end;
$$;

create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();

-- ---------------------------------------------------------------------------
-- Row-level security: every table, owner-only.
-- ---------------------------------------------------------------------------

alter table public.users enable row level security;
alter table public.projects enable row level security;
alter table public.rooms enable row level security;
alter table public.chats enable row level security;
alter table public.messages enable row level security;
alter table public.files enable row level security;
alter table public.image_assets enable row level security;
alter table public.chunks enable row level security;
alter table public.memories enable row level security;
alter table public.products enable row level security;
alter table public.decisions enable row level security;
alter table public.settings enable row level security;

create policy "own profile" on public.users
  for all to authenticated
  using (id = (select auth.uid()))
  with check (id = (select auth.uid()));

do $$
declare
  t text;
begin
  foreach t in array array[
    'projects', 'rooms', 'chats', 'messages', 'files', 'image_assets',
    'chunks', 'memories', 'products', 'decisions', 'settings'
  ]
  loop
    execute format(
      'create policy "owner access" on public.%I for all to authenticated
         using (user_id = (select auth.uid()))
         with check (user_id = (select auth.uid()))',
      t
    );
  end loop;
end;
$$;

-- ---------------------------------------------------------------------------
-- Storage: private buckets, objects stored under "<user_id>/..."
-- ---------------------------------------------------------------------------

insert into storage.buckets (id, name, public)
values ('files', 'files', false), ('images', 'images', false)
on conflict (id) do update set public = false;

create policy "own objects: select" on storage.objects
  for select to authenticated
  using (
    bucket_id in ('files', 'images')
    and (storage.foldername(name))[1] = (select auth.uid())::text
  );

create policy "own objects: insert" on storage.objects
  for insert to authenticated
  with check (
    bucket_id in ('files', 'images')
    and (storage.foldername(name))[1] = (select auth.uid())::text
  );

create policy "own objects: update" on storage.objects
  for update to authenticated
  using (
    bucket_id in ('files', 'images')
    and (storage.foldername(name))[1] = (select auth.uid())::text
  );

create policy "own objects: delete" on storage.objects
  for delete to authenticated
  using (
    bucket_id in ('files', 'images')
    and (storage.foldername(name))[1] = (select auth.uid())::text
  );

-- ===== 20260929000001_library.sql =====

-- Phase 2: reference library processing and retrieval.

-- ---------------------------------------------------------------------------
-- files: upload + resumable indexing state
-- ---------------------------------------------------------------------------

alter table public.files drop constraint files_status_check;
alter table public.files add constraint files_status_check
  check (status in ('uploading', 'pending', 'processing', 'indexed', 'failed'));
alter table public.files alter column status set default 'uploading';

-- Indexing runs in bounded steps (serverless time limits). `progress` records
-- where the next step resumes: { next_unit, total_units, warnings[] }.
alter table public.files add column progress jsonb not null default '{}'::jsonb;
-- A step holds a short lease so two open tabs never index the same file.
alter table public.files add column lease_until timestamptz;
alter table public.files add column attempts int not null default 0;

create index files_status_idx on public.files (status) where status in ('pending', 'processing');

-- ---------------------------------------------------------------------------
-- image_assets: where the image came from
-- ---------------------------------------------------------------------------

alter table public.image_assets add column source text not null default 'upload'
  check (source in ('upload', 'pdf_page', 'docx_image', 'chat'));
alter table public.image_assets add column metadata jsonb not null default '{}'::jsonb;
create index image_assets_message_idx on public.image_assets (message_id);

-- ---------------------------------------------------------------------------
-- Units: a file is indexed as numbered units (a PDF page, a .docx image, the
-- body text). Rows record their unit so an interrupted step can be redone
-- cleanly from the first unfinished unit.
-- ---------------------------------------------------------------------------

alter table public.chunks add column unit int not null default 0;
alter table public.image_assets add column unit int;
create index chunks_file_unit_idx on public.chunks (file_id, unit);
create index image_assets_file_unit_idx on public.image_assets (file_id, unit);

-- ---------------------------------------------------------------------------
-- Retrieval. SECURITY INVOKER (the default), so row-level security applies:
-- callers only ever match their own chunks.
-- ---------------------------------------------------------------------------

create or replace function public.match_chunks(
  query_embedding extensions.vector(1024),
  project_ids uuid[],
  match_count int default 8,
  min_similarity float default 0.0,
  prefer_room_id uuid default null
)
returns table (
  id uuid,
  file_id uuid,
  image_asset_id uuid,
  project_id uuid,
  room_id uuid,
  source_type text,
  content text,
  page int,
  metadata jsonb,
  similarity float,
  file_name text,
  project_name text,
  image_storage_path text,
  image_mime_type text
)
language sql
stable
set search_path = ''
as $$
  select
    c.id,
    c.file_id,
    c.image_asset_id,
    c.project_id,
    c.room_id,
    c.source_type,
    c.content,
    c.page,
    c.metadata,
    1 - (c.embedding operator(extensions.<=>) query_embedding) as similarity,
    coalesce(f.name, c.metadata->>'label', 'photo') as file_name,
    p.name as project_name,
    ia.storage_path as image_storage_path,
    ia.mime_type as image_mime_type
  from public.chunks c
  join public.projects p on p.id = c.project_id
  left join public.files f on f.id = c.file_id
  left join public.image_assets ia on ia.id = c.image_asset_id
  where c.embedding is not null
    and c.project_id = any (project_ids)
    and 1 - (c.embedding operator(extensions.<=>) query_embedding) >= min_similarity
  -- A small nudge toward the room being discussed, never enough to bury a
  -- clearly better match from elsewhere.
  order by (c.embedding operator(extensions.<=>) query_embedding)
    - case when prefer_room_id is not null and c.room_id = prefer_room_id then 0.03 else 0 end
  limit match_count;
$$;

grant execute on function public.match_chunks(extensions.vector, uuid[], int, float, uuid) to authenticated;

-- ---------------------------------------------------------------------------
-- Storage limits. Large PDFs are fine; the processing pipeline pages through.
-- ---------------------------------------------------------------------------

update storage.buckets set file_size_limit = 52428800 where id = 'files';   -- 50 MB
update storage.buckets set file_size_limit = 10485760 where id = 'images';  -- 10 MB

-- ===== 20260930000001_memory.sql =====

-- Phase 3: memory proposals, decisions and products.

-- Where a memory or decision came from, and the words that justify it.
alter table public.memories add column source text not null default 'manual'
  check (source in ('extracted', 'manual', 'import'));
alter table public.memories add column evidence text;
alter table public.decisions add column source text not null default 'manual'
  check (source in ('extracted', 'manual', 'import'));
alter table public.decisions add column evidence text;

-- Proposals are listed per chat message in the right panel.
create index memories_source_message_idx on public.memories (source_message_id);
create index decisions_source_message_idx on public.decisions (source_message_id);
create index products_source_message_idx on public.products (source_message_id);

-- ---------------------------------------------------------------------------
-- Memory retrieval: approved memories for a project plus household-wide ones,
-- nearest first. SECURITY INVOKER, so RLS applies.
-- ---------------------------------------------------------------------------

create or replace function public.match_memories(
  query_embedding extensions.vector(1024),
  project_id uuid,
  match_count int default 30
)
returns table (id uuid, similarity float)
language sql
stable
set search_path = ''
as $$
  select m.id, 1 - (m.embedding operator(extensions.<=>) query_embedding) as similarity
  from public.memories m
  where m.review_state = 'approved'
    and m.embedding is not null
    and (m.project_id = match_memories.project_id or m.project_id is null)
  order by m.embedding operator(extensions.<=>) query_embedding
  limit match_count;
$$;

grant execute on function public.match_memories(extensions.vector, uuid, int) to authenticated;

-- ===== 20261001000001_admin.sql =====

-- Phase 4: settings, import/export and the ChatGPT importer.

-- ---------------------------------------------------------------------------
-- System prompt history. `settings.system_prompt` stays the live copy; every
-- save and restore also records a version here.
-- ---------------------------------------------------------------------------

create table public.system_prompt_versions (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null default auth.uid() references public.users (id) on delete cascade,
  content text not null,
  -- 'original' | 'edited' | 'restored' | 'reset' | 'imported'
  label text not null default 'edited',
  note text,
  created_at timestamptz not null default now()
);
create index system_prompt_versions_user_idx on public.system_prompt_versions (user_id, created_at desc);

alter table public.system_prompt_versions enable row level security;
create policy "owner access" on public.system_prompt_versions for all to authenticated
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

-- ---------------------------------------------------------------------------
-- Imported conversations: where they came from, and memory extraction progress.
-- ---------------------------------------------------------------------------

-- ChatGPT's conversation id, so importing the same export twice is harmless.
alter table public.chats add column external_id text;
create unique index chats_external_id_unique on public.chats (user_id, external_id) where external_id is not null;

-- Memory extraction over imported chats runs in resumable steps.
alter table public.chats add column extraction_status text
  check (extraction_status in ('pending', 'running', 'done', 'failed'));
alter table public.chats add column extraction_next int not null default 0;
alter table public.chats add column extraction_error text;
alter table public.chats add column extraction_lease_until timestamptz;
create index chats_extraction_idx on public.chats (extraction_status) where extraction_status in ('pending', 'running');

-- ===== 20261006000001_ephemeral_messages.sql =====

-- Ephemeral advisor session messages for generation persistence.
-- Anonymous visitors (no user_id) can have responses continue server-side
-- even if they leave the page, switch apps, or browser suspends the tab.

create table public.ephemeral_messages (
  id uuid primary key default gen_random_uuid(),
  session_id uuid not null,
  role text not null check (role in ('user', 'assistant')),
  -- pending: generation in progress
  -- completed: generation finished successfully
  -- failed: generation failed
  status text not null default 'pending'
    check (status in ('pending', 'completed', 'failed')),
  content text not null default '',
  error text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index ephemeral_messages_session_idx on public.ephemeral_messages (session_id, created_at);
create index ephemeral_messages_status_idx on public.ephemeral_messages (session_id, status);

-- Auto-update updated_at
create trigger ephemeral_messages_updated_at before update on public.ephemeral_messages
  for each row execute function public.set_updated_at();

-- Clean up old sessions (older than 7 days)
create or replace function public.cleanup_ephemeral_messages()
returns void
language plpgsql
as $$
begin
  delete from public.ephemeral_messages
  where created_at < now() - interval '7 days';
end;
$$;

-- ===== 20261028000001_sms.sql =====

-- SMS sessions and processed-message dedup for Ask Cinq by text.
-- Apply in the Supabase dashboard before the Twilio number goes live.
-- Only the service-role key touches these tables: no grants to anon or
-- authenticated, so no signed-in user is needed and no visitor can read
-- another number's conversation.
create table public.sms_sessions (
  phone_number text primary key,
  opted_in boolean not null default false,
  advisor_id text,
  turns_by_advisor jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create trigger sms_sessions_updated_at before update on public.sms_sessions
  for each row execute function public.set_updated_at();

create table public.sms_processed_messages (
  message_sid text primary key,
  phone_number text not null,
  created_at timestamptz not null default now()
);

create index sms_processed_messages_phone_idx on public.sms_processed_messages (phone_number, created_at);

-- ===== 20261126000001_sms_metrics.sql =====

-- Operational measurements for Cinq by text: one row per incoming text and
-- one per text Cinq sends. Timings, counts, kinds and statuses only: never a
-- message's words, a photo, a phone number or an error message. A number is
-- stored as a keyed hash (number_key), so requests from one number can be
-- grouped (bursts, overlaps, active numbers) without storing the number.
-- Only the service-role key touches these: row level security is on with no
-- policies, and the public API roles have no grants, so the publishable key
-- can't read them. Rows are deleted after 90 days (src/lib/ops/retention.ts).
--
-- Additive and safe to run again: it only creates what doesn't exist yet and
-- never touches sms_sessions or sms_processed_messages. To undo it, run
-- supabase/rollback/20261126000001_sms_metrics.down.sql.
create table if not exists public.sms_requests (
  message_sid text primary key,
  number_key text not null,
  received_at timestamptz not null,
  -- Filled in when the request ends; still null after a few minutes means it ended in silence.
  finished_at timestamptz,
  has_text boolean not null default false,
  photo_count integer not null default 0,
  -- answered | fallback | stalled | system | duplicate | opted_out | error
  outcome text,
  advisor_id text,
  ack_ms integer,
  still_thinking_ms integer,
  answer_ms integer,
  texts_sent integer not null default 0,
  segments_sent integer not null default 0,
  send_failures integer not null default 0,
  save_failures integer not null default 0,
  -- Model use: one entry per call, {purpose, model, ms, input, output, cache_read, cache_write, searches}.
  model_calls jsonb not null default '[]'::jsonb,
  error_class text
);

create index if not exists sms_requests_received_idx on public.sms_requests (received_at);
create index if not exists sms_requests_number_idx on public.sms_requests (number_key, received_at);

-- Written when Twilio accepts a text, and again by Twilio's delivery reports,
-- which can arrive first: so only the sid is required.
create table if not exists public.sms_outbound (
  sid text primary key,
  request_sid text,
  -- ack | still_thinking | answer | fallback | stalled | system
  kind text,
  segments integer,
  submitted_at timestamptz,
  -- Twilio's latest status: queued | sent | delivered | undelivered | failed …
  status text,
  error_code text,
  status_at timestamptz,
  delivered_at timestamptz
);

create index if not exists sms_outbound_submitted_idx on public.sms_outbound (submitted_at);
create index if not exists sms_outbound_request_idx on public.sms_outbound (request_sid);

alter table public.sms_requests enable row level security;
alter table public.sms_outbound enable row level security;
revoke all on table public.sms_requests, public.sms_outbound from anon, authenticated;

-- ===== 20261126000002_sms_lockdown.sql =====

-- Lock the SMS tables to the server. sms_sessions holds conversations and
-- phone numbers, and sms_processed_messages holds phone numbers; both were
-- created without row level security, so with Supabase's default grants the
-- public (anon / publishable) key could read them through the Data API.
-- The app only ever uses the service-role key, which bypasses row level
-- security, so nothing Cinq does changes.
--
-- Safe to run again (each statement is idempotent) and changes no data.
-- To undo it, run supabase/rollback/20261126000002_sms_lockdown.down.sql.
alter table public.sms_sessions enable row level security;
alter table public.sms_processed_messages enable row level security;
revoke all on table public.sms_sessions, public.sms_processed_messages from anon, authenticated;

-- ===== 20261127000000_ephemeral_messages_lockdown.sql =====

-- Lock ephemeral_messages to the server. It was created (20261006000001)
-- without row level security, so with Supabase's default grants the public
-- (anon / publishable) key could read and write it through the Data API, and
-- it can hold message text. Nothing in the app has used it since the
-- persistent-answer code was removed (Oct 8, 2026); the server uses the
-- service-role key, which bypasses row level security, so nothing Cinq does
-- changes. The rows are kept: deciding what to do with them is separate.
--
-- Safe to run again (each statement is idempotent) and changes no data.
-- To undo it, run supabase/rollback/20261127000000_ephemeral_messages_lockdown.down.sql.
alter table if exists public.ephemeral_messages enable row level security;
alter table if exists public.ephemeral_messages force row level security;

do $$
begin
  if to_regclass('public.ephemeral_messages') is not null then
    revoke all on table public.ephemeral_messages from anon, authenticated;
  end if;
  if to_regprocedure('public.cleanup_ephemeral_messages()') is not null then
    revoke execute on function public.cleanup_ephemeral_messages() from public, anon, authenticated;
  end if;
end $$;

-- ===== 20261127000001_advisor_foundations.sql =====

-- The advisors' private intellectual foundations (docs/foundations.md).
--
-- advisor_layers holds every approved version of each advisor's identity,
-- foundation and experimental second layer, encrypted by the app before it
-- is stored (AES-256-GCM, a key that lives only in the server's settings):
-- this database never holds the text in the clear. A version, once stored,
-- can't be changed (a trigger refuses it); a change is a new version.
-- advisor_active says which architecture and versions each advisor uses;
-- every change to it is kept in advisor_active_history. advisor_events counts
-- fallbacks, unavailability and leak-guard hits: fixed codes, never text.
--
-- Only the service-role key touches these: row level security is on with no
-- policies, and the public API roles have no grants, as for the SMS tables.
-- Additive and safe to run again. To undo it, run
-- supabase/rollback/20261127000001_advisor_foundations.down.sql.
create table if not exists public.advisor_layers (
  id bigint generated always as identity primary key,
  advisor_id text not null,
  layer text not null check (layer in ('identity', 'foundation', 'foundation_l2')),
  version integer not null check (version > 0),
  ciphertext text not null,
  iv text not null,
  tag text not null,
  key_id text not null,
  -- Of the plaintext, checked after decryption.
  sha256 text not null,
  -- Where each part came from (interview, written refinement, AI-assisted, drafting), as recorded in the private source.
  provenance jsonb not null default '{}'::jsonb,
  approved_by text not null,
  approved_at timestamptz not null,
  approval_note text,
  -- approved | retired
  status text not null default 'approved' check (status in ('approved', 'retired')),
  created_at timestamptz not null default now(),
  unique (advisor_id, layer, version)
);

-- A stored version can be retired, never rewritten.
create or replace function public.advisor_layers_immutable() returns trigger
language plpgsql as $$
begin
  if tg_op = 'DELETE' then
    raise exception 'advisor_layers versions are kept; retire one instead';
  end if;
  if new.advisor_id is distinct from old.advisor_id or new.layer is distinct from old.layer or new.version is distinct from old.version
     or new.ciphertext is distinct from old.ciphertext or new.iv is distinct from old.iv or new.tag is distinct from old.tag
     or new.key_id is distinct from old.key_id or new.sha256 is distinct from old.sha256
     or new.provenance is distinct from old.provenance or new.approved_by is distinct from old.approved_by
     or new.approved_at is distinct from old.approved_at then
    raise exception 'advisor_layers versions are immutable; publish a new version';
  end if;
  return new;
end;
$$;
drop trigger if exists advisor_layers_immutable on public.advisor_layers;
create trigger advisor_layers_immutable before update or delete on public.advisor_layers
  for each row execute function public.advisor_layers_immutable();

create table if not exists public.advisor_active (
  advisor_id text primary key,
  architecture text not null default 'legacy' check (architecture in ('legacy', 'c2')),
  identity_version integer,
  foundation_version integer,
  -- The experimental second layer: null keeps it off.
  layer2_version integer,
  updated_by text not null,
  updated_at timestamptz not null default now(),
  -- Set by the app when C2 last loaded, for the unavailability threshold.
  last_loaded_at timestamptz,
  check (architecture = 'legacy' or (identity_version is not null and foundation_version is not null))
);

create table if not exists public.advisor_active_history (
  id bigint generated always as identity primary key,
  advisor_id text not null,
  architecture text not null,
  identity_version integer,
  foundation_version integer,
  layer2_version integer,
  updated_by text not null,
  changed_at timestamptz not null default now()
);

-- Every configuration change is kept (the app's last_loaded_at updates are not changes).
create or replace function public.advisor_active_record() returns trigger
language plpgsql as $$
begin
  if tg_op = 'UPDATE' and new.architecture is not distinct from old.architecture
     and new.identity_version is not distinct from old.identity_version
     and new.foundation_version is not distinct from old.foundation_version
     and new.layer2_version is not distinct from old.layer2_version then
    return new;
  end if;
  insert into public.advisor_active_history (advisor_id, architecture, identity_version, foundation_version, layer2_version, updated_by)
  values (new.advisor_id, new.architecture, new.identity_version, new.foundation_version, new.layer2_version, new.updated_by);
  return new;
end;
$$;
drop trigger if exists advisor_active_record on public.advisor_active;
create trigger advisor_active_record after insert or update on public.advisor_active
  for each row execute function public.advisor_active_record();

create table if not exists public.advisor_events (
  id bigint generated always as identity primary key,
  advisor_id text not null,
  at timestamptz not null default now(),
  -- fallback | unavailable | leak_guard
  kind text not null check (kind in ('fallback', 'unavailable', 'leak_guard')),
  -- A fixed reason code (or the channel, for the leak guard).
  reason text
);
create index if not exists advisor_events_at_idx on public.advisor_events (advisor_id, at);

alter table public.advisor_layers enable row level security;
alter table public.advisor_active enable row level security;
alter table public.advisor_active_history enable row level security;
alter table public.advisor_events enable row level security;
revoke all on table public.advisor_layers, public.advisor_active, public.advisor_active_history, public.advisor_events from anon, authenticated;
revoke all on function public.advisor_layers_immutable(), public.advisor_active_record() from anon, authenticated, public;
